def calc(expr):
    pos = 0

    def peek():
        nonlocal pos
        while pos < len(expr) and expr[pos] == ' ':
            pos += 1
        return expr[pos] if pos < len(expr) else None

    def consume(char=None):
        nonlocal pos
        while pos < len(expr) and expr[pos] == ' ':
            pos += 1
        if char is not None:
            if pos < len(expr) and expr[pos] == char:
                pos += 1
                return True
            return False
        if pos < len(expr):
            c = expr[pos]
            pos += 1
            return c
        return None

    def parse_number():
        nonlocal pos
        while pos < len(expr) and expr[pos] == ' ':
            pos += 1
        start = pos
        while pos < len(expr) and expr[pos].isdigit():
            pos += 1
        return int(expr[start:pos])

    def parse_unary():
        c = peek()
        if c == '-':
            consume('-')
            return -parse_unary()
        elif c == '+':
            consume('+')
            return parse_unary()
        else:
            return parse_primary()

    def parse_primary():
        c = peek()
        if c == '(':
            consume('(')
            result = parse_additive()
            consume(')')
            return result
        else:
            return parse_number()

    def parse_multiplicative():
        result = parse_unary()
        while peek() in ['*', '/']:
            op = consume()
            right = parse_unary()
            if op == '*':
                result = result * right
            else:  # op == '/'
                # Truncate toward zero
                result = int(result / right)
        return result

    def parse_additive():
        result = parse_multiplicative()
        while peek() in ['+', '-']:
            op = consume()
            right = parse_multiplicative()
            if op == '+':
                result = result + right
            else:  # op == '-'
                result = result - right
        return result

    return parse_additive()

